export const MONUMENTS = JSON.parse("[{\"id\":\"n6581377209\",\"kind\":\"memorial\",\"sub\":\"sculpture\",\"x\":-2472.8,\"z\":-1314.5},{\"id\":\"n4686521490\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"И. П. Павлов\",\"x\":-2876.9,\"z\":-1319.3,\"subject\":\"Q42985\"},{\"id\":\"n5825777998\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. Н. Ушакову\",\"x\":-2666.5,\"z\":-1278,\"subject\":\"Q70249189\",\"inscription\":\"В этом здании с 1948 по 1964 гг работал видный ученый-химик член-корреспондент Академии наук СССР Сергей Николаевич Ушаков\"},{\"id\":\"n6452791537\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. П. Линнику\",\"x\":-3094.1,\"z\":-1269.3,\"subject\":\"Q4262286\",\"inscription\":\"Здесь с 1926 по 1984 год работал академик Владимир Павлович Линник, выдающийся советский физик, Герой Социалистического Труд\"},{\"id\":\"n6452791538\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. И. Вавилову\",\"x\":-3099.5,\"z\":-1279.2,\"subject\":\"Q324968\",\"inscription\":\"Здесь с 1932 по 1951 год жил и работал академик Сергей Иванович Вавилов, выдающийся советский учёный, президент Академии наук СССР\"},{\"id\":\"n6452791539\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. С. Рождественскому\",\"x\":-3104.4,\"z\":-1288.1,\"subject\":\"Q4396191\",\"inscription\":\"В этом здании с 1916 по 1940 гг. жил и работал выдающийся советский физик, организатор и первый директор Государственного оптического института академик Дмитрий Сергеевич Рождественский\"},{\"id\":\"n6452791540\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Лебедеву\",\"x\":-3110.2,\"z\":-1298.7,\"subject\":\"Q4255674\",\"inscription\":\"Здесь с 1918 по 1968 год работал академик Александр Алексеевич Лебедев, выдающийся советский физик, Герой Социалистического Труда\"},{\"id\":\"n6452791541\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Н. Теренину\",\"x\":-3090.5,\"z\":-1262.8,\"subject\":\"Q4455594\",\"inscription\":\"Здесь с 1919 по 1967 год работал академик Александр Николаевич Теренин, выдающийся советский физик, Герой Социалистического Труда\"},{\"id\":\"n6452791542\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. В. Гребенщикову\",\"x\":-3087.9,\"z\":-1258,\"subject\":\"Q4148272\",\"inscription\":\"Здесь с 1918 по 1953 год работал академик Илья Васильевич Гребенщиков, выдающийся советский химик\"},{\"id\":\"n13474601312\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3038,\"z\":-1267.3},{\"id\":\"n8818516448\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. О. районному комитету РСДРП(б)\",\"x\":-5046.7,\"z\":-1266.3,\"inscription\":\"В этом доме в дни Октябрьского переворота 1917 г. находился и руководил на В. О-ве восставшим пролетариатом В. О. районный комитет Р.С.Д.Р.П. (большевиков). Поставлено в десятилетие Октября. Возобновлено в 1958 году.\"},{\"id\":\"n8818558773\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Социалистическому союзу рабочей молодежи\",\"x\":-5046,\"z\":-1265,\"inscription\":\"В этом доме в апреле 1917 года под руководством большевиков состоялось первое районное собрание молодежи, положившее начало созданию Социалистического союза рабочей молодежи Васильевского острова\"},{\"id\":\"n14044890010\",\"kind\":\"artwork\",\"sub\":\"mural\",\"x\":-4800.6,\"z\":-1246.3},{\"id\":\"n11510705251\",\"kind\":\"memorial\",\"name\":\"Подводникам лодки «Дельфин»\",\"x\":-6020.4,\"z\":-1286.5},{\"id\":\"n10680626028\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Экспериментальный дом серии БС\",\"x\":-6874.7,\"z\":-1243.7}]");
